const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const defaultConfig = { ...operatorDefaults, ...acsDefaults, name:'Ridgeview · East roof', mode:'IP Passthrough', ipType:'IPv4v6', lanIP:'10.1.1.1', dhcp:'Enabled', subnet:'255.255.255.0', mtu:'1500', band:'Band 48', selection:'Automatic', ssh:true, telnet:false, adminAccess:'LAN + management APN', acs:'https://acs.example.com', interval:'300', sas:'Google SAS', timezone:'UTC', apnMgmt:'ue-mgmt', apnData:'edge', firewall:true, ping:false, routeDest:'', routeGateway:'' };
