let config = {...defaultConfig,...(isDevice?{}:readStored('titan-demo-config',{}))};
const state = {page:location.hash.slice(1) || 'overview', tabs:{radio:'apn',network:'mode',system:'device',sas:'configuration',acs:'server'}, acsStatus:'Connected / simulated',acsCertificates:['demo-acs-ca.pem'], scenario:'connected', ethernetSpeed:1000, quality:72, tick:0, rsrp:-84.2,sinr:18.6,rsrq:-9.1, pci:190,qa:false,focus:false,paused:false,alignScenario:'normal',lastUpdate:Date.now(),tour:0,scanning:false,scanResults:false,diagnostic:false,diagnosticDone:false,dirty:false,lockDraft:null,sasRegistration:'Registered',sasGrant:'Authorized',sasCertificates:[{type:'SAS CA',name:'Demo trust root'},{type:'CBSD',name:'Demo device certificate'}],cpiPayload:{},cpiInstalledAt:'',crlName:'',forwards:[],routes:[]};
let savedTheme=readStored('titan-demo-dark',false); document.documentElement.classList.toggle('dark',savedTheme);
let toastTimer;
const pages=[['overview','LayoutDashboard','Overview'],['align','Crosshair','Align'],['radio','RadioTower','Radio'],['network','Network','Network'],['system','Settings2','System'],['diagnostics','Activity','Diagnostics']];
const brand = `<div class="brand"><div class="brandmark"><svg viewBox="0 0 32 40" fill="none" aria-hidden="true"><path d="M3 8 16 2 29 8 26 29 16 38 6 29Z" stroke="currentColor" stroke-width="1.4"/><path d="m8 11 8 4 8-4-4 12-4 7-4-7Z" fill="currentColor"/><path d="m10 17 4 2m8-2-4 2" stroke="#212720" stroke-width="2"/></svg></div><div><strong>TITAN</strong><small>WITCHER EDITION</small></div></div>`;
const button=(text,action,ic='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const pill=(text,type='green')=>`<span class="pill pill-${type}">${text}</span>`;
const note=text=>`<p class="note">${text}</p>`;
const field=(label,name,value,type='text',help='')=>`<label class="field">${label}<input aria-label="${esc(label)}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="1"':''} required>${help?`<small>${help}</small>`:''}</label>`;
const select=(label,name,value,options,help='')=>`<label class="field">${label}<select aria-label="${esc(label)}" name="${name}">${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;
const toggle=(label,name,checked,help)=>`<label class="toggle-row"><span>${label}<small>${help}</small></span><input type="checkbox" aria-label="${esc(label)}" name="${name}" ${checked?'checked':''}></label>`;
const actions = (label='Save changes') => `<div class="form-actions"><span class="muted text-[11px]">Changes apply to this demo only</span>${button('Discard','discard','','') }<button class="btn btn-primary" type="submit">${icon('Check')}${label}</button></div>`;
function toast(message) { const el=$('#toast'); el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200); }
function nav(page) { if(isDevice&&device?.busy){toast('Wait for the device operation to finish.');return;}if(state.dirty && page!==state.page) { confirmDialog('Leave unsaved changes?','Your edits on this screen have not been saved.',()=>{state.dirty=false;location.hash=page;},'Discard and leave');return; } location.hash=page; }
// Device screens change only once their data is in hand, so a transition never
// passes through a placeholder. Slow reads show a slim progress bar instead.
let navSerial=0;
async function ready(target) {
 const serial=++navSerial;
 if(!isDevice||!device?.prepare)return true;
 const bar=$('.nav-progress'),timer=setTimeout(()=>bar?.classList.add('active'),140);
 try{await device.prepare(target);}catch{}
 finally{clearTimeout(timer);if(serial===navSerial)bar?.classList.remove('active');}
 return serial===navSerial;
}
function prefetch(element) {
 if(!isDevice||!device?.prefetch||!device.authenticated)return;
 const link=element.closest('a[data-page],[data-tab]');if(!link)return;
 device.prefetch(link.dataset.page?{page:link.dataset.page}:{page:link.dataset.section,tab:link.dataset.tab});
}
function fresh() { if(isDevice)return device?.fresh()??false; return ['connected','weak','changed'].includes(state.scenario) && !state.paused; }
function shell() {
 if(state.page==='login') { renderLogin();dashboard.unmount();alignScreen.leave();alignScreen.unmount();if(isDevice)device?.mount();mountMotion($('#app'),'login');return; }
 $('#app').innerHTML=`<div class="${state.focus?'focus-align':''}"><aside class="sidebar">${brand}<div class="nav-label">DEVICE CONSOLE</div><nav class="side-nav" aria-label="Main navigation">${pages.map(([id,ic,label])=>`<a href="#${id}" data-page="${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}${label}${state.page===id?`<span class="nav-arrow">${icon('ChevronRight')}</span>`:''}</a>`).join('')}</nav><div class="side-foot"><button class="btn btn-small" data-action="tour" style="width:100%">${icon('CircleHelp')}Take a walkthrough</button><div class="side-unit mt-6"><span class="flex items-center gap-2">DEMO DEVICE</span><strong>${esc(config.name)}</strong><span class="code">TITAN 4000 / B48</span></div><div class="edition">${icon('ShieldCheck')} WITCHER UI / PREVIEW 02</div></div></aside><div class="main-shell"><header class="topbar"><div class="preview-context">UI preview<span>Simulated data · Settings stay in this browser</span></div><div class="top-actions"><button class="header-demo" data-action="qa">Demo controls</button><button class="icon-button" data-action="theme" aria-label="Toggle color theme">${icon(savedTheme?'Sun':'Moon')}</button><button class="icon-button" data-action="logout" aria-label="Show demo login">${icon('LogOut')}</button></div></header><main id="main" tabindex="-1">${renderPage()}<footer class="footer"><span>Titan 4000 <span class="mx-2">/</span> Witcher Edition <span class="mx-2">/</span> UI walkthrough</span><span>Preview 02 / Simulated data · <a href="/licenses/index.html" target="_blank" rel="noopener">Software licenses</a></span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${pages.map(([id,ic,label])=>`<a href="#${id}" data-page="${id}" class="${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</nav><div id="qa-root">${state.qa?qaPanel():''}</div></div>`;
 updateLive();
 syncTabIndicators();
 mountMotion($('#main'),state.page);
 if(isDevice)device.mount();
 syncDashboard();
 syncAlign();
}
function syncAlign() { if(state.page==='align'&&$('[data-align]'))alignScreen.mount($('#main'),alignSource());else alignScreen.unmount(); }
function syncDashboard() { if(state.page==='overview'&&$('[data-history]'))dashboard.mount($('#main'),isDevice?device.dashboard:{live:demoLive,history:demoHistory});else dashboard.unmount(); }
function head(eyebrow,title,sub,action='') { return `<div class="page-head"><div><h1>${title}</h1><p class="page-sub">${sub}</p></div>${action}</div>`; }
function renderPage() { if(isDevice){const page=device?.renderPage({head,tabs});if(page!==undefined)return page;} return ({overview,align,radio,network,system,diagnostics}[state.page]||overview)(); }
function metric(label,key,unit,foot,ic) { return `<div class="card metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value"><span data-live="${key}">—</span><small>${unit}</small></div><div class="metric-foot"><span data-quality="${key}">${foot}</span></div></div>`; }
function overview() {
 return renderDashboard({esc,icon,config,head,subtitle:esc(config.name)+' &nbsp;/&nbsp; <span data-device=serial>'+(isDevice?'—':'WITCHER-001')+'</span>',defaults:isDevice?{}:{band:'48',earfcn:'55990',serial:'WITCHER-001',customer:'198.51.100.24',network:'Witcher test network',management:'192.0.2.10'}});
}
// Simulated readings for the walkthrough, shaped like the device telemetry.
const demoTraffic={dl:42e6,ul:6e6};
function demoLive() {
 const active=fresh(),q=state.quality/100;
 if(active){demoTraffic.dl=Math.max(0,Math.min(340e6,demoTraffic.dl*.7+(60e6+q*190e6)*(.55+Math.random()*.6)*.3));demoTraffic.ul=Math.max(0,Math.min(48e6,demoTraffic.ul*.7+(5e6+q*30e6)*(.5+Math.random()*.7)*.3));}
 const mod=state.sinr>=22?'256QAM':state.sinr>=14?'64QAM':state.sinr>=6?'16QAM':'QPSK',ulmod=state.sinr>=16?'64QAM':state.sinr>=8?'16QAM':'QPSK',carriers=state.sinr>=15?3:state.sinr>=8?2:1,busy=demoTraffic.dl>120e6?carriers:demoTraffic.dl>40e6?Math.min(2,carriers):1;
 const list=[[190,55990,state.rsrp,state.sinr],[142,56188,state.rsrp-3.4,state.sinr-2.1],[73,56386,state.rsrp-6.2,state.sinr-4.4]].map(([pci,earfcn,rsrp,sinr],i)=>({role:i?'scc':'pcc',index:i,band:'48',earfcn,pci,bandwidth_mhz:20,rsrp,sinr,rsrq:state.rsrq,dl_modulation:i<busy?mod:'QPSK',dl_mcs:i<busy?Math.round(10+q*17):0,active:i<busy}));
 return {fresh:active,attached:state.scenario!=='searching',sampledAt:state.lastUpdate,dl_bps:demoTraffic.dl,ul_bps:demoTraffic.ul,rsrp:state.rsrp,sinr:state.sinr,rsrq:state.rsrq,cqi:Math.round(6+q*9),ri:2,dl:{modulation:mod,mcs:Math.round(10+q*17)},ul:{modulation:ulmod,mcs:Math.round(8+q*18)},configured:3,active:busy,bandwidth:60,carriers:list,radioAge:400,gps:{fix:true,latitude:33.51849,longitude:-86.81036,altitude_m:212,updated:new Date().toISOString()}};
}
async function demoHistory(window) {
 const span=WINDOWS.find(w=>w[0]===window)[2],count=Math.min(300,span/1000),step=span/count,now=Date.now(),points=[];
 for(let i=0;i<count;i++){const t=now-span+i*step,phase=i/count*Math.PI*4,sinr=16+Math.sin(phase)*4+Math.random(),dl=(90+Math.sin(phase*1.7)*60+Math.random()*40)*1e6;points.push({t,dl,dl_max:dl*1.35,ul:dl/9,ul_max:dl/6,rsrp:-86+Math.sin(phase)*3,sinr,rsrq:-9,cqi:11,carriers:sinr>15?3:2,dl_mod:sinr>18?'256QAM':'64QAM'});}
 const avg=key=>points.reduce((a,p)=>a+p[key],0)/points.length;
 return {window,step_ms:step,now_unix_ms:now,oldest_unix_ms:now-span,points,summary:{dl_avg:avg('dl'),dl_peak:Math.max(...points.map(p=>p.dl_max)),ul_avg:avg('ul'),ul_peak:Math.max(...points.map(p=>p.ul_max)),rsrp_avg:avg('rsrp'),sinr_avg:avg('sinr'),rsrq_avg:avg('rsrq'),cqi_avg:11,carriers:{'1':0,'2':.4,'3':.6,'4':0},dl_modulation:{QPSK:0,'16QAM':.05,'64QAM':.55,'256QAM':.4},coverage:1}};
}
const dashboard=new Dashboard();
