const sim=isDevice?null:new AlignSim();
// The demo grant follows the SAS screen so the grant finding can be tried.
let demoBase,demoSnap;
const demoAlign=sim&&{kind:'demo',subscribe:fn=>sim.subscribe(fn),pose:()=>sim.pose(),
 snapshot(){const s=sim.snapshot();if(s!==demoBase){demoBase=s;demoSnap=s&&{...s,sas:s.attached?{grant:state.sasGrant,registration:state.sasRegistration}:s.sas};}return demoSnap;}};
const alignSource=()=>isDevice?device?.align:demoAlign;
function health(title,sub,ic,status,key) {return `<div class="health-row">${icon(ic)}<div><strong>${title}</strong><small>${sub}</small></div><span data-health="${key}">${status}</span></div>`;}
function align() {return renderAlign({esc,icon,button,head,pill,focus:state.focus,config:{pciMode:config.pciMode,pciTargets:config.pciTargets||[]},screen:alignScreen});}
function tabs(page,items) {return `<div class="panel-tabs" data-tablist="${page}" role="tablist" aria-label="${page} sections">${items.map(([id,title])=>`<button role="tab" aria-selected="${state.tabs[page]===id}" class="${state.tabs[page]===id?'active':''}" data-tab="${id}" data-section="${page}">${title}</button>`).join('')}<span class="tab-indicator" aria-hidden="true"></span></div>`;}
function syncTabIndicators() { $$('[data-tablist]').forEach(list=>{const active=$('.active',list),indicator=$('.tab-indicator',list);if(!active||!indicator)return;indicator.style.width=active.offsetWidth+'px';indicator.style.transform=`translateX(${active.offsetLeft}px)`;}); }
function renderTab(section) {
 const template=document.createElement('template');template.innerHTML=renderPage();
 const panel=$(`[data-tab-panel="${section}"]`),next=template.content.querySelector(`[data-tab-panel="${section}"]`);
 if(!panel||!next){shell();return;}
 panel.replaceChildren(...next.childNodes);
 $$(`[data-section="${section}"]`).forEach(button=>{const active=state.tabs[section]===button.dataset.tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});
 syncTabIndicators();updateLive();if(isDevice)device.mount();
}
function radio() { let content=''; const tab=state.tabs.radio;
 if(tab==='apn')content=`<div class="card card-pad"><div class="card-head"><div><h2>PDN & APN profiles</h2><p class="muted text-xs mt-2">Management and customer bearer profiles.</p></div>${pill('Dual stack')}</div><form data-form="apn"><div class="grid md:grid-cols-2 gap-5"><div class="p-5 border border-[var(--line)]"><div class="flex justify-between mb-5"><h3>Management</h3>${pill('Class 1 / CID 1','neutral')}</div>${field('APN name','apnMgmt',config.apnMgmt)}<div class="mt-5">${select('IP support','mgmtType','IPv4v6',['IPv4v6'],'Management bearer · Titan access and services')}</div></div><div class="p-5 border border-[var(--line)]"><div class="flex justify-between mb-5"><h3>Customer data</h3>${pill('Class 2 / CID 2','neutral')}</div>${field('APN name','apnData',config.apnData)}<div class="mt-5">${select('IP support','dataType','IPv4v6',['IPv4v6'],'Customer bearer · IPv4 and delegated IPv6')}</div></div></div><div class="mt-5">${note('Class ordering is fixed in this walkthrough: management on CID 1 and customer data on CID 2. Both profiles use IPv4v6.')}</div>${actions('Save profiles')}</form></div>`;
 if(tab==='selection')content=`<section class="card card-pad"><div class="card-head"><h2>Radio preferences</h2>${pill('LTE')}</div><form data-form="radio"><div class="form-grid">${select('Operating band','band',config.band,['Band 48','Band 42','Band 43','Automatic'])}${select('Cell selection','selection',config.selection,['Automatic','Best SINR','Best RSRP'])}</div><div class="mt-6">${note('These controls demonstrate the configuration flow. Available bands and cell-selection behavior will be verified against the target firmware.')}</div>${actions('Apply preferences')}</form></section>`;
 if(tab==='lock')content=renderCellLock({config,state,select,toggle,button,note,actions,esc,pill});
 if(tab==='scan')content=`<section class="card card-pad"><div class="card-head"><div><h2>Nearby cells</h2><p class="muted text-xs mt-2">Explore a simulated area scan.</p></div>${button(state.scanning?'Scanning…':'Scan cells','scan','ScanLine','btn-primary')}</div>${note('An active scan may interrupt a real LTE connection. This preview runs a simulated scan only.')}<div class="mt-6" id="scan-results">${scanResults()}</div></section>`;
 return `${head('','Radio','Manage bearers, band preferences, and cell selection.')}${tabs('radio',[['apn','APN profiles'],['selection','Band & selection'],['lock','PCI lock'],['scan','Cell scan']])}<div data-tab-panel="radio">${content}</div>`; }
function scanResults() { if(state.scanning)return `<div class="position-empty skeleton">${icon('RadioTower')}<h3>Searching for cells…</h3><p class="muted text-xs mt-2">Simulated scan in progress</p></div>`;if(!state.scanResults)return `<div class="position-empty">${icon('ScanLine')}<h3>No scan results</h3><p class="muted text-xs mt-2">Run a scan to compare nearby cells.</p></div>`;return `<div class="table-wrap"><table><thead><tr><th>Cell</th><th>Band / EARFCN</th><th>RSRP</th><th>SINR</th><th>Status</th></tr></thead><tbody>${[[190,-84.2,18.6],[142,-91.8,12.4],[73,-103.1,3.8]].map(([pci,r,s])=>`<tr><td>PCI ${pci}</td><td>48 / 55990</td><td>${r} dBm</td><td>${s} dB</td><td>${pill(pci===190?'Serving':'Detected',pci===190?'green':'neutral')}</td></tr>`).join('')}</tbody></table></div>`; }
function network() {let content=''; const tab=state.tabs.network;
 if(tab==='mode')content=`<section class="card card-pad"><div class="card-head"><div><h2>Connection mode</h2><p class="muted text-xs mt-2">Choose how the Titan hands off customer traffic.</p></div>${icon('Network')}</div><form data-form="mode"><div class="form-grid">${select('Operating mode','mode',config.mode,['IP Passthrough','NAT / Router'],'IP Passthrough delivers the customer bearer to your downstream router.')}${select('IP type','ipType',config.ipType,['IPv4v6','IPv4'],'IPv4v6 is required for delegated IPv6 in passthrough.')}</div><div class="mt-6">${note('Changing mode restarts the connection. The demo will show the restart and the new local management address.')}</div>${actions('Apply mode')}</form></section><div class="grid md:grid-cols-2 gap-4 mt-4"><section class="card card-pad"><div class="eyebrow">MANAGEMENT PATH</div><h2>192.0.2.10</h2><p class="muted text-xs mt-3">${esc(config.apnMgmt)} · Class 1 · Titan services</p></section><section class="card card-pad"><div class="eyebrow">CUSTOMER PATH</div><h2>198.51.100.24</h2><p class="muted text-xs mt-3">${esc(config.apnData)} · Class 2 · IPv6-PD: 2001:db8:100::/56</p></section></div>`;
 if(tab==='lan')content=`<section class="card card-pad"><h2 class="mb-6">Local network</h2><form data-form="lan"><div class="form-grid">${field('Management address','lanIP',config.lanIP,'text','Use an IPv4 address, for example 10.1.1.1.')}${field('Subnet mask','subnet',config.subnet)}${select('DHCP server','dhcp',config.dhcp,['Enabled','Disabled'])}${field('MTU','mtu',config.mtu,'number','Valid range: 576–1500 bytes.')}</div>${actions()}</form></section>`;
 if(tab==='firewall')content=`<section class="card card-pad"><h2>Firewall & access</h2><form data-form="firewall">${toggle('Stateful firewall','firewall',config.firewall,'Filter unsolicited inbound traffic.')}${toggle('Respond to customer WAN ping','ping',config.ping,'Allow ICMP echo on the customer interface.')}${actions()}</form></section><section class="card card-pad mt-4"><div class="card-head"><h2>Port forwards</h2>${button('Add rule','add-forward','Plus')}</div>${state.forwards.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>External → internal</th><th>Protocol</th><th>Action</th></tr></thead><tbody>${state.forwards.map((f,i)=>`<tr><td>${esc(f.name)}</td><td>${esc(f.port)} → ${esc(f.ip)}:${esc(f.port)}</td><td>TCP</td><td><button class="btn btn-small" data-remove-forward="${i}" aria-label="Delete ${esc(f.name)}">${icon('Trash2')}</button></td></tr>`).join('')}</tbody></table></div>`:note('No demo forwarding rules. Add one to test the rule editor.')}</section>`;
 if(tab==='routes')content=`<section class="card card-pad"><div class="card-head"><h2>Routing table</h2>${button('Add route','add-route','Plus')}</div><div class="table-wrap"><table><thead><tr><th>Destination</th><th>Gateway</th><th>Interface</th><th>Source</th></tr></thead><tbody><tr><td>0.0.0.0/0</td><td>192.0.2.1</td><td>Management PDN</td><td>Simulated kernel</td></tr><tr><td>10.1.1.0/24</td><td>On link</td><td>LAN</td><td>Simulated kernel</td></tr>${state.routes.map(r=>`<tr><td>${esc(r.dest)}</td><td>${esc(r.gateway)}</td><td>Management PDN</td><td>Demo configuration</td></tr>`).join('')}</tbody></table></div><div class="mt-5">${note('Saved routes and active kernel routes are distinct. Added demo routes are labeled configuration; this preview cannot verify forwarding.')}</div></section>`;
 return `${head('','Network','Operating mode, LAN configuration, and routing.')}${tabs('network',[['mode','Operating mode'],['lan','LAN & DHCP'],['firewall','Firewall'],['routes','Routes']])}<div data-tab-panel="network">${content}</div>`; }
function system() {let content='';const tab=state.tabs.system;
 if(tab==='device')content=`<section class="card card-pad"><div class="card-head"><h2>Device identity</h2>${pill('WITCHER-001','neutral')}</div><form data-form="device"><div class="form-grid">${field('Device name','name',config.name)}${select('Time zone','timezone',config.timezone,['UTC','America/Chicago','America/New_York','America/Denver','America/Los_Angeles'])}</div>${actions()}</form></section><div class="grid md:grid-cols-2 gap-4 mt-4"><section class="card card-pad"><h2>Configuration backup</h2><p class="muted text-xs mt-3 mb-5">Download the demo settings as JSON. No credentials or device secrets are included.</p>${button('Download demo backup','backup','Download')}</section><section class="card card-pad"><h2>Restart device</h2><p class="muted text-xs mt-3 mb-5">Walk through a restart and automatic reconnection. Your demo settings are retained.</p>${button('Restart demo','reboot','RotateCcw')}</section></div>`;
 if(tab==='access')content=`<section class="card card-pad"><h2 class="mb-6">Management access</h2><form data-form="access">${select('Allow management from','adminAccess',config.adminAccess,['LAN + management APN','LAN only'])}${toggle('SSH service','ssh',config.ssh,'Encrypted shell access for operators.')}${toggle('Telnet service','telnet',config.telnet,'Legacy shell access.')}${actions()}</form></section><section class="card card-pad mt-4"><h2 class="mb-4">Administrator password</h2><p class="muted text-xs mb-5">Test password validation using dummy values. Passwords are not stored.</p><form data-form="password"><div class="form-grid">${field('New demo password','password','','password','At least 12 characters. Use dummy text only.')}${field('Confirm password','confirm','','password')}</div>${actions('Change demo password')}</form></section>`;
 if(tab==='sas')content=renderSas({config,state,field,select,toggle,button,pill,note,actions,esc,tabs});
 if(tab==='services')content=renderAcs({config,state,tabs,toggle,pill,button,actions,esc,note});
 if(tab==='firmware')content=`<section class="card card-pad"><div class="card-head"><div><h2>Firmware update</h2><p class="muted text-xs mt-2">Review the upload, validation, and restart experience.</p></div>${pill('Preview only','amber')}</div><dl class="definition !mt-0 !pt-0 !border-0 mb-6"><div><dt>Interface build</dt><dd>Witcher UI / Preview 02</dd></div><div><dt>Target firmware family</dt><dd>4172 · baseline pending verification</dd></div></dl><div class="p-7 border border-dashed border-[var(--line)] text-center"><div class="flex justify-center mb-3">${icon('Upload')}</div><h3>Try a firmware update</h3><p class="muted text-xs mt-2 mb-5">Use the included sample to walk through the update.<br>No image is uploaded or installed.</p>${button('Use sample firmware','firmware','Upload','btn-primary')}</div><div class="mt-5">${note('A real update will validate the image, write the inactive bank, and keep the recovery bank available. This demo only simulates those screens.')}</div></section>`;
 return `${head('','System','Device settings, operator access, and maintenance.')}${tabs('system',[['device','Device'],['access','Access'],['services','ACS'],['sas','SAS'],['firmware','Firmware']])}<div data-tab-panel="system">${content}</div>`; }
function diagnostics() {return `${head('','Diagnostics','Check connectivity and review device events.',button('Export report','report','Download','hide-phone'))}<div class="grid lg:grid-cols-[1.3fr_1fr] gap-4"><section class="card card-pad"><div class="card-head"><h2>Connection check</h2>${icon('Activity')}</div><p class="muted text-xs mb-5">Check each part of the path from the Titan to the internet.</p><div id="diagnostic-result">${diagnosticResult()}</div><div class="mt-6">${button(state.diagnostic?'Checking…':'Run connection check','diagnose','Play','btn-primary')}</div></section><section class="card card-pad"><h2 class="mb-5">Device snapshot</h2><dl class="definition !border-0 !pt-0 !mt-0"><div><dt>Serial</dt><dd>WITCHER-001</dd></div><div><dt>Model</dt><dd>Titan 4000</dd></div><div><dt>Management</dt><dd>${esc(config.lanIP)}</dd></div><div><dt>Interface build</dt><dd>Preview 02</dd></div><div><dt>LTE band</dt><dd>48</dd></div><div><dt>Scenario</dt><dd>${esc(state.scenario)}</dd></div></dl></section></div><section class="card card-pad mt-4"><div class="card-head"><h2>Event log</h2>${pill('Simulated','neutral')}</div><div class="log">[demo] Witcher interface started
[demo] Configuration loaded from this browser
[radio] Scenario: ${esc(state.scenario)} · PCI ${state.pci}
[network] Mode: ${esc(config.mode)} · ${esc(config.ipType)}
[preview] No connection to a Titan device</div></section>`; }
function diagnosticResult() {if(state.diagnostic)return `<div class="note skeleton">${icon('RefreshCw')}Checking the simulated connection…</div>`;if(!state.diagnosticDone)return note('Run a check to see the simulated radio, bearer, DNS, and internet results.');const ok=fresh();return ['Ethernet link','LTE attachment','SAS authorization','Customer bearer','DNS resolution','Internet reachability'].map((label,i)=>health(label,i===0?'Local cable and downstream link':'Simulated result',i===0||ok?'CircleCheck':'AlertTriangle',i===0||ok?'Pass':'Unavailable','check'+i)).join('');}
function qaPanel() {return `<section class="qa-panel card" aria-label="Demo controls"><div class="card-head !mb-2"><h2>Demo controls</h2><button class="icon-button !h-8 !min-w-8" data-action="qa" aria-label="Close demo controls">${icon('X')}</button></div><p class="muted text-[11px]">These controls simulate the device for QA.</p><label class="field">Connection scenario<select name="scenario">${[['connected','Connected'],['weak','Weak signal'],['searching','Searching for network'],['stale','Stale telemetry'],['changed','Serving cell changed'],['expired','Session expired']].map(([v,l])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Ethernet speed<select name="ethernetSpeed" aria-label="Ethernet speed">${[1000,100,10,0].map(v=>`<option value="${v}" ${state.ethernetSpeed===v?'selected':''}>${v===1000?'1 Gbps':v+' Mbps'}${v===0?' / No link':''}</option>`).join('')}</select></label><label class="field">Antenna position <span class="muted text-[11px]">Move to turn the simulated antenna. The tower is near 83.</span><input aria-label="Simulated antenna position" type="range" id="quality" min="0" max="100" value="${state.quality}"></label><div class="flex justify-between muted text-[10px] -mt-3"><span>Turn left</span><span>Turn right</span></div><label class="field">Align scenario<select name="alignScenario" aria-label="Align scenario">${[['normal','Clean link'],['interference','Interference'],['imbalance','Weak receive path'],['sidelobe','Side lobe'],['slow','Realistic modem (slow)'],['fast','Future 1 Hz source']].map(([v,l])=>`<option value="${v}" ${state.alignScenario===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="mt-5 grid grid-cols-2 gap-2">${button('Guided tour','tour','CircleHelp','btn-small')}${button('Reset demo','reset','RotateCcw','btn-small')}</div><p class="muted text-[10px] mt-4">Saved settings stay in this browser. Signal and position marks reset on refresh.</p></section>`;}
function renderLogin() { $('#app').innerHTML=`<div class="login-shell"><section class="login-art"><div class="login-photo" aria-hidden="true"></div>${brand}<div class="login-caption"><h2 class="login-headline">Titan 4000</h2><p>Device management</p></div><div class="login-identity"><div class="login-mac"><span class="login-mac-label">MAC address</span><span class="code" data-login-mac>${isDevice?'Loading…':'02:00:00:A1:B2:C3'}</span></div><div class="login-version code" aria-label="Firmware version">${esc(witcherLabel)}</div></div></section><section class="login-form"><div class="login-topline"><span>UI preview</span><button type="button" class="icon-button" data-action="theme" aria-label="Toggle color theme">${icon(savedTheme?'Sun':'Moon')}</button></div><h1>${state.scenario==='expired'?'Session expired.':'Welcome back.'}</h1><p class="muted text-sm">${state.scenario==='expired'?'Sign in again to continue your walkthrough.':'Sign in to manage your Titan.'}</p><form data-form="login"><div class="field"><label for="login-password">Password</label><div class="password-field"><input id="login-password" type="password" placeholder="Enter password" autocomplete="off" aria-describedby="first-password preview-login"><button type="button" class="password-toggle" data-action="show-password" aria-label="Show password" aria-pressed="false">${icon('Eye')}</button></div></div><p id="first-password" class="login-help">Use the administrator password configured on this unit. Contact your network operator if you need help signing in.</p><button class="btn btn-primary login-submit" type="submit">Enter demo ${icon('ArrowRight')}</button><p id="preview-login" class="login-preview-note">Preview only. Leave the password blank to explore.</p></form></section></div>`; }
function updateLive() {
 if(state.page==='login')return;
 const slowEthernet=state.ethernetSpeed!==1000;
 $$('[data-health=ethernet]').forEach(el=>{setLiveText(el,state.ethernetSpeed===1000?'1 Gbps':state.ethernetSpeed+' Mbps');el.classList.toggle('ethernet-slow',slowEthernet);el.setAttribute('aria-label',state.ethernetSpeed===0?'Ethernet disconnected, 0 Mbps':`Ethernet ${state.ethernetSpeed} Mbps${slowEthernet?', below gigabit':''}`);});
 $$('[data-ethernet-speed]').forEach(el=>setLiveText(el,state.ethernetSpeed===1000?'1 Gbps':state.ethernetSpeed+' Mbps'));
 $$('[data-ethernet-link]').forEach(el=>el.classList.toggle('ethernet-slow',slowEthernet));
 $$('[data-ethernet-notice]').forEach(el=>{el.hidden=!slowEthernet;el.textContent=state.ethernetSpeed===0?'No Ethernet link. Check the cable and PoE connection.':'Ethernet is below 1 Gbps. Check the cable and the connected port.';});
 const active=fresh(); const unavailable=!active; const stale=state.scenario==='stale'||state.paused;
 const values={rsrp:unavailable?'—':state.rsrp.toFixed(1),sinr:unavailable?'—':state.sinr.toFixed(1),rsrq:unavailable?'—':state.rsrq.toFixed(1),uptime:`${Math.floor(state.tick/60)}m ${state.tick%60}s`,pci:state.pci};
 if(isDevice)Object.assign(values,device.values());
 // The Align screen owns its readings; generic updates skip its subtree.
 const outside=selector=>$$(selector).filter(el=>!el.closest('[data-align]'));
 outside('[data-live]').forEach(el=>setLiveText(el,values[el.dataset.live]));
 outside('[data-status]').forEach(el=>setLiveHTML(el,pill(state.paused?'Paused':({connected:'Connected',weak:'Weak signal',searching:'Searching',stale:'Data stale',changed:'Cell changed',restarting:'Reconnecting'})[state.scenario]||'Offline',active?(state.scenario==='weak'?'amber':'green'):'amber')));
 $$('[data-cell]').forEach(el=>setLiveText(el,`PCI ${state.pci}`));
 $$('[data-connection-title]').forEach(el=>setLiveText(el,active?'Connected to the network':stale?'Signal updates unavailable':'Looking for a connection'));
 outside('[data-freshness]').forEach(el=>{const age=Math.max(0,Math.floor((Date.now()-state.lastUpdate)/1000));el.textContent=active?(isDevice&&age>=2?`Updated ${age}s ago`:'Updated just now'):state.paused?'Readings paused':`${age}s since update`;});
 outside('[data-quality]').forEach(el=>{el.textContent=unavailable?'Waiting for fresh data':el.dataset.quality==='sinr'?(state.sinr>=20?'Excellent':state.sinr>=10?'Good':'Low quality'):el.dataset.quality==='rsrp'?(state.rsrp>=-90?'Good':state.rsrp>=-105?'Fair':'Weak signal'):el.dataset.quality==='uptime'?'Demo session':'Reference signal quality';});
 for(const key of ['radio','sas','data']) $$(`[data-health=${key}]`).forEach(el=>el.textContent=active?({radio:'Attached',sas:state.sasGrant,data:state.sasGrant==='Authorized'?'Ready':'Waiting for grant'})[key]:stale?'Unknown':'Waiting');
 if(isDevice)device.update();
 if(state.page==='overview')dashboard.update();
 if(alignScreen.mounted)alignScreen.update();
}
function showModal(html) { showDialog($('#modal'),html); }
function closeModal() { closeDialog($('#modal')); }
function confirmDialog(title,body,callback,label='Continue') {showModal(`${icon('Info')}<h2>${title}</h2><p>${body}</p><div class="modal-actions">${button('Cancel','close-modal')}<button class="btn btn-primary" id="confirm-action">${label}</button></div>`);$('#confirm-action').onclick=()=>{closeModal();callback();};}
const tourSteps=[['overview','Overview','Overview puts radio quality, bearer addresses, and connection health together. Everything you see here is simulated.'],['align','Antenna alignment','Use Demo controls to turn the antenna. Mark a position, hold still for three readings, then adjust and compare. Try sound and focus mode on your phone.'],['radio','APN profiles','Management and customer APNs have clear roles. Band preferences and a simulated cell scan are one tab away.'],['network','Network settings','Try switching between passthrough and NAT. The preview walks through a restart and updates the management address.'],['system','System settings','Try saving settings, downloading a backup, and the sample firmware update. Demo controls also lets you test failures and reset everything.']];
function tour(step=0){state.qa=false;state.focus=false;alignScreen.leave();state.tour=step;const [page,title,body]=tourSteps[step];state.page=page;history.replaceState(null,'','#'+page);shell();showModal(`<div class="flex justify-between items-center"><span class="tour-number">0${step+1}</span><span class="muted text-xs">${step+1} of ${tourSteps.length}</span></div><h2>${title}</h2><p>${body}</p><div class="modal-actions">${button('Close tour','close-modal')}${step>0?button('Back','tour-back'):''}${button(step===tourSteps.length-1?'Start exploring':'Next','tour-next','ArrowRight','btn-primary')}</div>`);}
function setScenario(scenario) {
 stopCapture({expired:'expired',stale:'stale',changed:'cell'}[scenario]??'scenario');state.scenario=scenario;state.paused=false;
 if(scenario==='weak')state.quality=17;
 if(scenario==='connected')state.quality=72;
 state.pci=scenario==='changed'?142:190;
 sim?.setControls({scenario,quality:state.quality,paused:false});
 if(scenario==='expired'){alignScreen.leave();state.dirty=false;state.focus=false;state.page='login';history.replaceState(null,'','#login');}
 sample();if(scenario==='expired')transitionContent(shell,{auth:true});else shell();
}
// Overview tiles follow the simulated antenna, so both screens agree.
function sample() {if(!fresh()||!sim)return;const s=sim.snapshot(),mean=list=>{const v=(list||[]).filter(Number.isFinite);return v.length?v.reduce((a,b)=>a+b,0)/v.length:null;},power=list=>{const v=(list||[]).filter(Number.isFinite);return v.length?10*Math.log10(v.reduce((a,x)=>a+10**(x/10),0)/v.length):null;};const rsrp=power(s?.signal?.rsrp),sinr=power(s?.quality?.cinr)??s?.quality?.sinr,rsrq=mean(s?.signal?.rsrq);if(Number.isFinite(rsrp))state.rsrp=rsrp;if(Number.isFinite(sinr))state.sinr=sinr;if(Number.isFinite(rsrq))state.rsrq=rsrq;state.lastUpdate=s?.collectedAt||Date.now();}
function stopCapture(reason='stale') {alignScreen.cancelCapture(reason);}
function tick() {if(!isDevice){state.tick++;if(!document.hidden)sample();}updateLive();}
function silence(){alignScreen.silence();}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Demo download prepared.');}
function reboot(message='Restarting the demo connection…'){stopCapture('restart');state.scenario='restarting';sim?.setControls({scenario:'restarting'});silence();shell();showModal(`<div class="skeleton">${icon('RefreshCw')}</div><h2>${message}</h2><p>Your simulated device will reconnect in a few seconds. No command was sent to a Titan.</p><div class="note">Local management address: ${esc(config.lanIP)}</div>`);setTimeout(()=>{state.scenario='connected';state.quality=72;sim?.setControls({scenario:'connected',quality:72});sample();closeModal();shell();toast('Demo connection restored.');},3500);}
function storeConfig(){try{localStorage.setItem('titan-demo-config',JSON.stringify(config));}catch{toast('Browser storage unavailable. Changes remain in this session.');}}
function saveConfig(form){if(isDevice){device.submit(form);return;}const kind=form.dataset.form;const data=Object.fromEntries(new FormData(form));
 if(kind==='cell-lock'){
  const value=readCellLock(form,config);const error=validateCellLock(value);if(error){toast(error);return;}
  confirmDialog('Apply cell selection?','This saves the PCI selection in the demo. It does not change the live Titan or force the simulated serving cell.',()=>{Object.assign(config,value);storeConfig();state.lockDraft=null;state.dirty=false;shell();toast('Cell selection saved.');},'Apply cell selection');return;
 }
 if(kind.startsWith('sas-')){
  const error=validateSas(kind,data);if(error){toast(error);return;}
  if(kind==='sas-certificate'){
   const files=[['certBundle','P12 bundle'],['certCa','SAS CA'],['certCbsd','CBSD'],['certKey','CBSD key']].filter(([key])=>data[key]?.name);
   state.sasCertificates=files.map(([key,type])=>({type,name:data[key].name}));config.sasCertFormat=data.sasCertFormat;
  } else if(kind==='sas-crl'){
   if(form.elements.sasLocalCrl.checked&&!data.crlFile?.name&&!state.crlName){toast('Select a dummy CRL file before enabling local CRL.');return;}
   if(data.crlFile?.name)state.crlName=data.crlFile.name;
  } else if(kind==='sas-cpi'){
   state.cpiInstalledAt=new Date().toISOString();
   state.cpiPayload={cpiProtectedHeader:data.cpiProtectedHeader||'',cpiEncodedData:data.cpiEncodedData||'',cpiSignature:data.cpiSignature||''};
  }
  for(const [key,value]of Object.entries(data))if(key in operatorDefaults&&typeof value==='string')config[key]=value;
  for(const checkbox of $$('input[type=checkbox]',form))config[checkbox.name]=checkbox.checked;
  storeConfig();state.dirty=false;state.cpiMethod=null;state.certFormat=null;shell();toast(kind==='sas-certificate'?'Demo certificate filenames recorded. No files were uploaded or validated.':kind==='sas-cpi'?'Demo CPI data saved. No signing or validation performed.':'SAS demo settings saved.');return;
 }

 if(kind.startsWith('acs-')){
  const error=validateAcs(kind,data);if(error){toast(error);return;}
  if(kind==='acs-certificate'){
   if(!data.acsCertificate?.name){toast('Select a dummy certificate file.');return;}
   if(!state.acsCertificates.includes(data.acsCertificate.name))state.acsCertificates.push(data.acsCertificate.name);
  }else{
   for(const [key,value]of Object.entries(data))if(key in acsDefaults&&typeof value==='string')config[key]=value;
   for(const checkbox of $$('input[type=checkbox]',form))if(checkbox.name in acsDefaults)config[checkbox.name]=checkbox.checked;
   state.acsStatus=config.acsEnabled?'Configured / simulated':'Disabled';storeConfig();
  }
  state.dirty=false;shell();toast(kind==='acs-certificate'?'Demo certificate filename recorded. No file was uploaded.':'ACS demo settings saved. Passwords were not stored.');return;
 }
 if(kind==='login'){state.scenario='connected';state.quality=72;sim?.setControls({scenario:'connected',quality:72});state.dirty=false;nav('overview');return;}
 if(kind==='password'){if(data.password.length<12){toast('Use at least 12 characters for the demo password.');return;}if(data.password!==data.confirm){toast('The passwords do not match.');return;}form.reset();state.dirty=false;toast('Demo password change complete. No password was stored.');return;}
 if(kind==='forward'){if(!validIP(data.ip)||!/^\d+$/.test(data.port)||Number(data.port)<1||Number(data.port)>65535){toast('Enter a valid IPv4 address and a port from 1 to 65535.');return;}state.forwards.push(data);closeModal();shell();toast('Demo forwarding rule added.');return;}
 if(kind==='route'){const [ip,prefix]=data.dest.split('/');if(!validIP(ip)||!/^\d+$/.test(prefix||'')||Number(prefix)>32||!validIP(data.gateway)){toast('Enter an IPv4 CIDR destination and a valid gateway.');return;}state.routes.push(data);closeModal();shell();toast('Demo route saved as configuration.');return;}
 if(kind==='lan'&&(!validIP(data.lanIP)||!validMask(data.subnet)||Number(data.mtu)<576||Number(data.mtu)>1500)){toast('Check the IPv4 address, subnet mask, and MTU (576–1500).');return;}
 if(kind==='apn'&&(!/^[a-zA-Z0-9.-]+$/.test(data.apnMgmt)||!/^[a-zA-Z0-9.-]+$/.test(data.apnData))){toast('APN names may contain letters, numbers, dots, and hyphens.');return;}
 const persist=()=>{for(const [key,value]of Object.entries(data))if(key in config)config[key]=value;for(const checkbox of $$('input[type=checkbox]',form))config[checkbox.name]=checkbox.checked;if(kind==='mode')config.lanIP=config.mode==='IP Passthrough'?'10.1.1.1':'192.168.0.1';try{localStorage.setItem('titan-demo-config',JSON.stringify(config));}catch{toast('Browser storage is unavailable. Changes last for this session only.');}state.dirty=false;if(kind==='mode'||kind==='apn')reboot('Applying demo settings…');else{shell();toast('Changes saved to this browser’s demo.');}};
 if(kind==='mode'||kind==='apn')confirmDialog('Apply and reconnect?',`This simulates a connection restart. ${kind==='mode'?'Local access becomes '+(data.mode==='IP Passthrough'?'10.1.1.1':'192.168.0.1')+'.':''} Your live Titan is unaffected.`,persist,'Apply demo changes');else persist();
}
function validIP(value){const parts=value.split('.');return parts.length===4&&parts.every(p=>/^\d{1,3}$/.test(p)&&Number(p)<=255);}
function validMask(value){if(!validIP(value))return false;const bits=value.split('.').map(v=>Number(v).toString(2).padStart(8,'0')).join('');return /^1+0+$/.test(bits);}
function firmware(){showModal(`${icon('Upload')}<h2>Ready to update.</h2><p>Sample image: <strong>titan-witcher-ui-preview.prg</strong><br>Illustrative size: 38.6 MB<br>Settings: preserved · Target: inactive bank</p>${note('This is a sample workflow. No real file was selected, validated, or uploaded.')}<div class="modal-actions">${button('Cancel','close-modal')}${button('Simulate update','firmware-go','Upload','btn-primary')}</div>`);}
function firmwareGo(){showModal(`${icon('RefreshCw')}<h2>Simulating firmware update…</h2><p id="firmware-phase">1 / 3 · Checking sample image</p><progress id="firmware-progress" max="3" value="1" class="w-full accent-[var(--accent)]" aria-label="Simulated update progress"></progress>`);setTimeout(()=>{if($('#firmware-phase')){$('#firmware-phase').textContent='2 / 3 · Preparing inactive bank (simulated)';$('#firmware-progress').value=2;}},1000);setTimeout(()=>{if($('#firmware-phase')){$('#firmware-phase').textContent='3 / 3 · Restarting (simulated)';$('#firmware-progress').value=3;}},2000);setTimeout(()=>{showModal(`${icon('CircleCheck')}<h2>Demo update complete.</h2><p>The simulated device is back online. A real build will require image verification and bench qualification.</p><div class="modal-actions">${button('Back to system','close-modal','Check','btn-primary')}</div>`);},3200);}
const handlers={
 'acs-connect':()=>{if(state.dirty){toast('Save ACS settings before testing the connection.');return;}if(!config.acsEnabled){toast('Enable TR-069 to simulate an ACS connection.');return;}state.acsStatus='Connected / simulated';shell();toast('Simulated ACS connection successful. No request was sent.');},
 'show-password':()=>{const input=$('#login-password');const show=input.type==='password';input.type=show?'text':'password';const control=$('[data-action=show-password]');control.innerHTML=icon(show?'EyeOff':'Eye');control.setAttribute('aria-label',show?'Hide password':'Show password');control.setAttribute('aria-pressed',String(show));},
 'open-align':()=>nav('align'),
 'open-lock':()=>{state.tabs.radio='lock';nav('radio');},
 'lock-add':()=>{state.lockDraft=readCellLock($('[data-form=cell-lock]'),config);state.lockDraft.pciTargets.push({pci:''});state.dirty=true;shell();},
 'lock-current':()=>{state.lockDraft=readCellLock($('[data-form=cell-lock]'),config);if(!state.lockDraft.pciTargets.some(t=>Number(t.pci)===state.pci))state.lockDraft.pciTargets.push({pci:String(state.pci)});state.dirty=true;shell();},
 'sas-register':()=>confirmDialog('Simulate SAS registration?','This sets the demo registration to Registered and grant to Authorized. No SAS messages are sent.',()=>{state.sasRegistration='Registered';state.sasGrant='Authorized';shell();toast('Simulated registration complete.');},'Simulate registration'),
 'sas-deregister':()=>confirmDialog('Deregister demo CBSD?','The simulated grant will be removed. A real deregistration would interrupt service.',()=>{state.sasRegistration='Unregistered';state.sasGrant='No grant';shell();toast('Demo CBSD deregistered.');},'Deregister demo'),
 'sas-relinquish':()=>confirmDialog('Relinquish demo grant?','Registration remains, but the simulated spectrum grant will be removed.',()=>{state.sasGrant='No grant';shell();toast('Demo grant relinquished.');},'Relinquish demo grant'),
 'sas-restore-ca':()=>confirmDialog('Restore the demo CA certificate?','This restores the sample trust-root entry.',()=>{state.sasCertificates=state.sasCertificates.filter(c=>c.type!=='SAS CA');state.sasCertificates.unshift({type:'SAS CA',name:'Demo trust root'});shell();toast('Demo CA entry restored.');},'Restore demo CA'),
 'sas-clear-cpi':()=>confirmDialog('Clear demo CPI data?','Clears CPI payload, installer identity and installation timestamp from the preview.',()=>{state.cpiPayload={};state.cpiInstalledAt='';config.sasCpiId='';config.sasCpiName='';config.sasCpiRegistered=false;storeConfig();state.dirty=false;shell();toast('Demo CPI data cleared.');},'Clear demo CPI'),
qa:()=>{state.qa=!state.qa;$('#qa-root').innerHTML=state.qa?qaPanel():'';if(state.qa)reveal($('#qa-root').firstElementChild);},theme:()=>{savedTheme=!savedTheme;document.documentElement.classList.toggle('dark',savedTheme);try{localStorage.setItem('titan-demo-dark',JSON.stringify(savedTheme));}catch{}const el=$('[data-action=theme]');if(el)el.innerHTML=icon(savedTheme?'Sun':'Moon');},logout:()=>nav('login'),tour:()=>{if(state.dirty){confirmDialog('Start the walkthrough?','Unsaved edits on this screen will be discarded.',()=>{state.dirty=false;tour();},'Start tour');}else tour();},'tour-next':()=>state.tour===tourSteps.length-1?closeModal():tour(state.tour+1),'tour-back':()=>tour(state.tour-1),'close-modal':closeModal,
 focus:()=>{state.focus=!state.focus;shell();},audio:()=>alignScreen.toggleAudio(),wake:()=>alignScreen.toggleWake(),pause:()=>{state.paused=!state.paused;if(state.paused){alignScreen.cancelCapture('paused');alignScreen.silence();}sim?.setControls({paused:state.paused});shell();},mark:()=>alignScreen.mark(),
 'clear-positions':()=>alignScreen.clearPositions(),export:()=>alignScreen.exportCsv(),
 discard:()=>{state.dirty=false;state.lockDraft=null;state.cpiMethod=null;state.certFormat=null;shell();toast('Unsaved edits discarded.');},backup:()=>download('titan-demo-config.json',{source:'SIMULATED UI WALKTHROUGH',config}),report:()=>download('titan-demo-diagnostics.json',{source:'SIMULATED',scenario:state.scenario,config,signal:{sinr:state.sinr,rsrp:state.rsrp},pci:state.pci}),
 reboot:()=>confirmDialog('Restart the demo device?','The interface will show a short restart and reconnect sequence. Saved demo settings are retained.',()=>reboot(),'Restart demo'),firmware,'firmware-go':firmwareGo,
 scan:()=>{if(state.scanning)return;confirmDialog('Run a simulated cell scan?','On a real device an active scan can interrupt service. This scan uses sample cells only.',()=>{state.scanning=true;shell();setTimeout(()=>{state.scanning=false;state.scanResults=true;if(state.page==='radio'&&state.tabs.radio==='scan')shell();toast('Simulated scan complete. 3 cells found.');},2400);},'Start scan');},
 diagnose:()=>{if(state.diagnostic)return;state.diagnostic=true;state.diagnosticDone=false;shell();setTimeout(()=>{state.diagnostic=false;state.diagnosticDone=true;if(state.page==='diagnostics')shell();toast('Simulated connection check complete.');},1800);},
 'add-forward':()=>showModal(`<h2>Add a forwarding rule</h2><p>This rule is stored in the current demo session.</p><form data-form="forward"><div class="form-grid">${field('Rule name','name','Example service')}${field('TCP port','port','8080','number')}${field('Internal IPv4 address','ip','192.168.0.100')}</div><div class="modal-actions">${button('Cancel','close-modal')}<button class="btn btn-primary" type="submit">Add demo rule</button></div></form>`),
 'add-route':()=>showModal(`<h2>Add a static route</h2><p>Save a demo route configuration.</p><form data-form="route"><div class="form-grid">${field('Destination CIDR','dest','203.0.113.0/24')}${field('Gateway','gateway','192.0.2.1')}</div><div class="modal-actions">${button('Cancel','close-modal')}<button class="btn btn-primary" type="submit">Add demo route</button></div></form>`),
 reset:()=>confirmDialog('Start fresh?','This clears your saved demo settings, position marks, and session rules.',()=>{config={...defaultConfig};try{localStorage.removeItem('titan-demo-config');}catch{}state.ethernetSpeed=1000;state.routes=[];state.forwards=[];state.dirty=false;state.focus=false;alignScreen.reset();state.alignScenario='normal';sim?.setControls({alignScenario:'normal'});state.scanning=false;state.scanResults=false;state.diagnosticDone=false;state.lockDraft=null;state.cpiPayload={};state.cpiInstalledAt='';state.crlName='';state.cpiMethod=null;state.certFormat=null;state.sasRegistration='Registered';state.sasGrant='Authorized';state.sasCertificates=[{type:'SAS CA',name:'Demo trust root'},{type:'CBSD',name:'Demo device certificate'}];state.tabs={radio:'apn',network:'mode',system:'device',sas:'configuration',acs:'server'};state.acsStatus='Connected / simulated';state.acsCertificates=['demo-acs-ca.pem'];setScenario('connected');toast('Demo reset to its starting state.');},'Reset demo')
};
document.addEventListener('click',event=>{const navLink=event.target.closest('a[data-page]');if(navLink){event.preventDefault();nav(navLink.dataset.page);return;}const acsDelete=event.target.closest('[data-acs-delete]');if(acsDelete){const index=Number(acsDelete.dataset.acsDelete);confirmDialog('Delete demo ACS certificate?','This removes the filename from the preview.',()=>{state.acsCertificates.splice(index,1);shell();},'Delete certificate');return;}const lockRemove=event.target.closest('[data-lock-remove]');if(lockRemove){state.lockDraft=readCellLock($('[data-form=cell-lock]'),config);state.lockDraft.pciTargets.splice(Number(lockRemove.dataset.lockRemove),1);state.dirty=true;shell();return;}const tab=event.target.closest('[data-tab]');if(tab){if(isDevice&&device?.busy){toast('Wait for the device operation to finish.');return;}if(state.tabs[tab.dataset.section]===tab.dataset.tab)return;const switchTab=async()=>{state.tabs[tab.dataset.section]=tab.dataset.tab;state.lockDraft=null;state.cpiMethod=null;state.certFormat=null;state.dirty=false;
  // Acknowledge the click at once; the panel follows when its data is ready.
  const list=tab.closest('[role=tablist]');if(list){$$('[role=tab]',list).forEach(button=>{button.classList.toggle('active',button===tab);button.setAttribute('aria-selected',String(button===tab));});syncTabIndicators();}
  if(!await ready({page:tab.dataset.section,tab:tab.dataset.tab})||state.tabs[tab.dataset.section]!==tab.dataset.tab)return;
  swapContent($(`[data-tab-panel="${tab.dataset.section}"]`),()=>{renderTab(tab.dataset.section);$(`[data-section="${tab.dataset.section}"][data-tab="${tab.dataset.tab}"]`)?.focus({preventScroll:true});});};if(state.dirty)confirmDialog('Leave unsaved changes?','Edits on this tab have not been saved.',switchTab,'Discard and switch');else switchTab();return;}const remove=event.target.closest('[data-remove-forward]');if(remove){state.forwards.splice(Number(remove.dataset.removeForward),1);shell();return;}const action=event.target.closest('[data-action]');if(action&&!action.disabled)handlers[action.dataset.action]?.();});
document.addEventListener('submit',event=>{if(event.target.matches('[data-form]')){event.preventDefault();saveConfig(event.target);}});
document.addEventListener('input',event=>{if(event.target.id==='quality'){const value=Number(event.target.value);if(!fresh())setScenario('connected');if(state.scenario==='weak'){state.scenario='connected';sim?.setControls({scenario:'connected'});const scenario=$('[name=scenario]');if(scenario)scenario.value='connected';}state.quality=value;const slider=$('#quality');if(slider)slider.value=value;sim?.setControls({quality:value});sample();updateLive();return;}if(event.target.closest('form[data-form]:not([data-form=login])')&&!event.target.closest('dialog'))state.dirty=true;});
document.addEventListener('change',event=>{if(event.target.matches('input[type=checkbox]')&&event.target.form?.dataset.form?.startsWith('acs-')){const group=event.target.form.querySelector(`[data-acs-group="${event.target.name}"]`);if(group)group.disabled=!event.target.checked;}if(event.target.name==='ethernetSpeed'){state.ethernetSpeed=Number(event.target.value);updateLive();}if(event.target.name==='scenario')setScenario(event.target.value);if(event.target.name==='alignScenario'){state.alignScenario=event.target.value;sim?.setControls({alignScenario:state.alignScenario});}
 if(event.target.name==='pciMode'){state.lockDraft=readCellLock(event.target.form,config);state.dirty=true;shell();}
 if(['sasCpiMethod','sasCertFormat'].includes(event.target.name)){const target=event.target;const chosen=target.value;target.value=target.name==='sasCpiMethod'?(state.cpiMethod||config.sasCpiMethod):(state.certFormat||config.sasCertFormat);const change=()=>{state.dirty=false;if(target.name==='sasCpiMethod')state.cpiMethod=chosen;else state.certFormat=chosen;shell();};confirmDialog('Switch input format?','Unsaved edits in this form will be discarded.',change,'Switch format');}
});
window.addEventListener('hashchange',()=>{if(isDevice&&device?.busy){history.replaceState(null,'','#'+state.page);return;}if(isDevice&&!device.authenticated&&location.hash!=='#login'){history.replaceState(null,'','#login');return;}const previous=state.page;const next=location.hash.slice(1)||'overview';if(state.dirty&&next!==state.page){history.replaceState(null,'','#'+state.page);confirmDialog('Leave unsaved changes?','Your current changes have not been saved.',()=>{state.dirty=false;nav(next);},'Discard and leave');return;}state.qa=false;state.lockDraft=null;state.cpiMethod=null;state.certFormat=null;state.page=[...pages.map(p=>p[0]),'login'].includes(next)?next:'overview';if(state.page!=='align'){state.focus=false;alignScreen.leave();}const auth=previous==='login'||next==='login',page=state.page;
 $$('a[data-page]').forEach(link=>{const active=link.dataset.page===page;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
 (auth?Promise.resolve(true):ready({page})).then(current=>{if(!current||state.page!==page)return;const show=()=>{window.scrollTo(0,0);shell();$('#main')?.focus({preventScroll:true});};
  // Sign-in changes the whole frame; ordinary pages keep the shell and fade in.
  if(auth)transitionContent(show,{auth});else{show();enter($('#main'));}});});
for(const type of ['pointerover','focusin','touchstart'])document.addEventListener(type,event=>{if(event.target instanceof Element)prefetch(event.target);},{passive:true});
document.body.insertAdjacentHTML('beforeend','<div class="nav-progress" aria-hidden="true"></div>');
document.addEventListener('visibilitychange',()=>{if(document.hidden){alignScreen.cancelCapture('hidden');alignScreen.silence();}else updateLive();});
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue='';}});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
window.addEventListener('resize',syncTabIndicators);
if(isDevice){device=createDeviceRuntime({state,config,shell,renderLogin,updateLive,tick,nav,toast,confirmDialog,closeModal,stopCapture,handlers,esc,transitionContent}, {json:import.meta.env.MODE==='rust-device'});device.start();}else{sim.setControls({quality:state.quality,scenario:state.scenario,alignScenario:state.alignScenario,paused:state.paused});sim.start();shell();setInterval(tick,1000);}
